import {money,person} from './night-data.js';
export function registerAmounts(s){const t=s.transaction,last=s.lastSale&&s.time-s.lastSale.time<8?s.lastSale:null,source=t||last;if(!source)return null;const paid=t?['change','receipt','complete'].includes(t.stage):true;return{total:source.total,tender:paid?source.tender:null,due:paid?source.tender-source.total:null,change:paid?source.change:0,done:!t,id:source.id,stage:t?.stage||'complete',items:t?.items.length,scanned:t?.scanned.length};}
export function drawRegister(screen,s){const c=screen.ctx,a=registerAmounts(s);c.fillStyle='#06160d';c.fillRect(0,0,1024,384);c.fillStyle='#a4c993';c.font='26px monospace';c.fillText('EXIT 9 / '+(!s.power?'NO POWER':a?.done?'交易完成 / PAID':'CASH REGISTER'),26,31);if(!s.power){c.font='64px monospace';c.fillText('电源中断',300,225);screen.texture.needsUpdate=true;return;}if(!a){c.font='42px monospace';c.fillText('等待顾客与商品',320,205);screen.texture.needsUpdate=true;return;}c.strokeStyle='#34513a';c.lineWidth=2;c.beginPath();c.moveTo(512,49);c.lineTo(512,311);c.moveTo(22,178);c.lineTo(1002,178);c.stroke();const fields=[['应收 TOTAL',a.total],['实收 CASH',a.tender],['应找 CHANGE',a.due],['已找 GIVEN',a.change]];fields.forEach(([label,value],i)=>{const x=28+i%2*512,y=67+Math.floor(i/2)*132;c.fillStyle='#a0b891';c.font='28px monospace';c.fillText(label,x,y);c.fillStyle=i===2?'#f0d69b':'#d4edbf';c.font='bold 76px monospace';c.fillText(value==null?'—':money(value),x,y+84,470);});c.fillStyle='#9eb794';c.font='25px monospace';const name=person(s,a.id)?.cn||'';c.fillText(a.done?name+' · 交易结清，顾客离场':a.stage==='scan'?name+' · 已扫 '+a.scanned+'/'+a.items+' 件':a.stage==='cash'?'请收取柜台上的付款现金':'找齐自动结账 · Backspace 撤回未完成找零',26,367,970);screen.texture.needsUpdate=true;}
